mapper.sql:
where r.del_flag = '0'


        and r.tenant_id = #{bo.tenantId}


        and r.policy_no = #{bo.policyNo}


        and date_format(r.create_time, '%Y%m%d') >= date_format(#{bo.params.beginTime}, '%Y%m%d')


        and date_format(r.create_time, '%Y%m%d') <= date_format(#{bo.params.endTime}, '%Y%m%d')
